SELECT c.id,c.generation,c.payload FROM sidecar_commands c JOIN participant_assignments p ON p.thread_id=c.thread_id AND p.participant_id=c.participant_id LEFT JOIN sidecar_conversations t ON t.thread_id=c.thread_id AND t.agent_id=c.agent_id WHERE c.agent_id=$1 AND c.owner_instance_id=$2 AND c.acked_at IS NULL AND c.finished_at IS NULL AND c.kind='invoke' AND t.storage='postgres' AND c.generation=p.generation AND c.owner_instance_id=p.owner_instance_id ORDER BY c.observed_at,c.id;
